1	#!/usr/bin/env node
2	// Manages the local `.env` across environment tiers (dev/test/sit/uat/staging/prod).
3	//
4	// Storage: .env.sample documents every key with a `# scope:shared|tier|personal|auto`
5	// comment on its own line above the key. Real values live in gitignored
6	// .env.shared (same across all tiers) and .env.<tier> (differs per tier) —
7	// never committed.
8	//
9	// Usage:
10	//   node scripts/switchEnv.mjs                — report the currently active tier
11	//   node scripts/switchEnv.mjs init            — scaffold .env.shared + every
12	//                                                 .env.<tier> at once (skips files
13	//                                                 that already exist), so a dev can
14	//                                                 fill in all tokens in one pass
15	//                                                 instead of tier by tier
16	//   node scripts/switchEnv.mjs validate [--live] — check every existing .env.shared /
17	//                                                 .env.<tier> file against
18	//                                                 .env.sample's schema, plus
19	//                                                 cross-checks (OCAPI host vs
20	//                                                 config/<tier>.js, Contentful
21	//                                                 environment id vs tier). With
22	//                                                 --live, also makes a real
23	//                                                 read-only Contentful Delivery
24	//                                                 API call AND a real SLAS guest
25	//                                                 (client_credentials) token
26	//                                                 request per tier, confirming
27	//                                                 the credentials actually work
28	//                                                 — not just that they're set
29	//   node scripts/switchEnv.mjs <tier>          — switch to <tier>, merging
30	//                                                 .env.shared + .env.<tier> into
31	//                                                 .env (tier values win on
32	//                                                 collision) and stamping
33	//                                                 ENVIRONMENT_NAME + DEPLOY_TARGET
34	//
35	// `init` also auto-fetches CONTENTFUL_ENVIRONMENT_ID, CONTENTFUL_DELIVERY_TOKEN,
36	// and CONTENTFUL_PREVIEW_TOKEN for every tier once .env.shared has a
37	// CONTENTFUL_MANAGEMENT_TOKEN + CONTENTFUL_SPACE_ID — reusing the same Content
38	// Management API read (client.apiKey.getMany / client.previewApiKey.get) and
39	// the same @ZimmermannAU/tier-1-approvers write gate as `npm run
40	// config:contentful` (scripts/contentful/setup/getConfig.mjs). The environment
41	// id comes from the same call — an API key's `environments` link only ever
42	// points at a real environment, so finding a token for a tier also confirms
43	// that tier's environment exists. It only reads existing API keys/environments
44	// — it never creates new ones in Contentful.
45	//
46	// SFCC values (org id, short code, OCAPI host, SLAS client id/secret) are NOT
47	// auto-fetched: there's no discovery API (you need the short code to call any
48	// SFCC API in the first place), and OAuth client secrets are never retrievable
49	// after creation. See .docs/integration/01-sfcc.md — these remain manual entry.
50	import fs from 'node:fs';
51	import os from 'node:os';
52	import path from 'node:path';
53	import { execSync } from 'node:child_process';
54	import { createClient as createContentfulClient } from './contentful/setup/_shared.mjs';
55	
56	const ROOT = process.cwd();
57	const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];
58	// DEPLOY_TARGET picks config/{target}.js in pwa-kit-runtime's getConfig(), and also
59	// names the config file on disk for the cross-checks below. `prod` is the only tier
60	// where the local slug and the file/MRT target name diverge — see
61	// config/production.js and the `push:prod -t production` npm script.
62	const DEPLOY_TARGET_MAP = {
63	  dev: 'dev',
64	  test: 'test',
65	  sit: 'sit',
66	  uat: 'uat',
67	  staging: 'staging',
68	  prod: 'production',
69	};
70	// Confirmed environment strategy (2026-07-11): single Contentful space, per-tier
71	// environment id. `prod` is the only tier that doesn't just reuse its own slug.
72	const CONTENTFUL_ENV_MAP = {
73	  dev: 'dev',
74	  test: 'test',
75	  sit: 'sit',
76	  uat: 'uat',
77	  staging: 'staging',
78	  prod: 'master',
79	};
80	// `validate --live` runs sequentially across all 6 tiers for both checks — a single
81	// stalled sandbox must fail fast rather than hang the whole command.
82	const LIVE_CHECK_TIMEOUT_MS = 10_000;
83	
84	function readEnvFile(filePath) {
85	  if (!fs.existsSync(filePath)) return null;
86	  const entries = [];
87	  for (const raw of fs.readFileSync(filePath, 'utf8').split('\n')) {
88	    const line = raw.trim();
89	    if (!line || line.startsWith('#')) continue;
90	    const eqIdx = line.indexOf('=');
91	    if (eqIdx === -1) continue;
92	    entries.push([line.slice(0, eqIdx).trim(), line.slice(eqIdx + 1).trim()]);
93	  }
94	  return entries;
95	}
96	
97	// Section headers look like `# ── Commerce / SFCC ───────────────`.
98	const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
99	// Scope tags are their own comment line immediately above the KEY=value line
100	// (not trailing on the same line) — a trailing comment would make a blank
101	// placeholder look non-empty to the pre-commit .env.sample secret guard,
102	// which just checks whether anything follows the `=`.
103	const SCOPE_TAG_RE = /^#\s*scope:(shared|tier|personal|auto)\s*$/;
104	
105	function parseSample() {
106	  const samplePath = path.join(ROOT, '.env.sample');
107	  const parsed = [];
108	  let currentSection = null;
109	  let pendingScope = null;
110	  for (const raw of fs.readFileSync(samplePath, 'utf8').split('\n')) {
111	    const line = raw.trim();
112	    const sectionMatch = line.match(SECTION_HEADER_RE);
113	    if (sectionMatch) {
114	      currentSection = sectionMatch[1];
115	      continue;
116	    }
117	    const scopeMatch = line.match(SCOPE_TAG_RE);
118	    if (scopeMatch) {
119	      pendingScope = scopeMatch[1];
120	      continue;
121	    }
122	    if (!line || line.startsWith('#')) continue;
123	    if (!pendingScope) continue; // a KEY=value line with no scope tag above it — not managed
124	    const eqIdx = line.indexOf('=');
125	    if (eqIdx === -1) {
126	      pendingScope = null;
127	      continue;
128	    }
129	    parsed.push({
130	      key: line.slice(0, eqIdx).trim(),
131	      value: line.slice(eqIdx + 1).trim(),
132	      scope: pendingScope,
133	      section: currentSection || 'Other',
134	    });
135	    pendingScope = null;
136	  }
137	  return parsed;
138	}
139	
140	// Groups already-ordered entries by their .env.sample section, preserving the
141	// order sections first appear in. Used to print generated files with the same
142	// "# ── Section ──" grouping .env.sample has, instead of one flat key list.
143	function groupBySection(entries) {
144	  const groups = [];
145	  const bySection = new Map();
146	  for (const entry of entries) {
147	    if (!bySection.has(entry.section)) {
148	      const group = { section: entry.section, entries: [] };
149	      bySection.set(entry.section, group);
150	      groups.push(group);
151	    }
152	    bySection.get(entry.section).entries.push(entry);
153	  }
154	  return groups;
155	}
156	
157	const SAMPLE = parseSample();
158	const SHARED_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'shared');
159	const TIER_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'tier');
160	const PERSONAL_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'personal');
161	const SHARED_KEYS = new Set(SHARED_ENTRIES.map((entry) => entry.key));
162	const TIER_KEYS = new Set(TIER_ENTRIES.map((entry) => entry.key));
163	const PERSONAL_KEYS = new Set(PERSONAL_ENTRIES.map((entry) => entry.key));
164	// Everything that legitimately lives in .env.shared — shared (centralizable)
165	// plus personal (tier-independent, but per-developer and never centralized).
166	const SHARED_FILE_ENTRIES = [...SHARED_ENTRIES, ...PERSONAL_ENTRIES];
167	const SHARED_FILE_KEYS = new Set([...SHARED_KEYS, ...PERSONAL_KEYS]);
168	const AUTO_KEYS = new Set(SAMPLE.filter((entry) => entry.scope === 'auto').map((entry) => entry.key));
169	
170	function scaffold(filePath, keys, label, carryDefaults) {
171	  const header = carryDefaults
172	    ? `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
173	      `# Gitignored — never commit this file. Values already in .env.sample (known\n` +
174	      `# public identifiers, e.g. GTM container ID) are carried over as a starting point.\n\n`
175	    : `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
176	      `# Gitignored — never commit this file. Tier-specific values always start blank\n` +
177	      `# here (even if .env.sample shows an example) — never copy another tier's value.\n\n`;
178	  const body =
179	    groupBySection(keys)
180	      .map(({ section, entries }) => {
181	        const groupLines = entries.map(({ key, value }) => `${key}=${carryDefaults ? value : ''}`);
182	        return `# ── ${section} ──\n${groupLines.join('\n')}`;
183	      })
184	      .join('\n\n') + '\n';
185	  fs.writeFileSync(filePath, header + body);
186	  const blankCount = carryDefaults ? keys.filter(({ value }) => !value).length : keys.length;
187	  console.log(
188	    `Created ${path.relative(
189	      ROOT,
190	      filePath,
191	    )} — fill in the ${blankCount} blank value(s) before switching to this tier.`,
192	  );
193	  return blankCount;
194	}
195	
196	function reportCurrent() {
197	  const current = readEnvFile(path.join(ROOT, '.env'));
198	  const envName = current?.find(([key]) => key === 'ENVIRONMENT_NAME')?.[1] || '(not set)';
199	  console.log(`Current tier: ${envName}`);
200	  printUsage();
201	}
202	
203	function printUsage() {
204	  console.log(`\nAvailable tiers: ${TIERS.join(', ')}`);
205	  console.log('Usage:');
206	  console.log('  npm run env                 — report the current tier');
207	  console.log('  npm run env -- init            — scaffold every .env.shared / .env.<tier> at once,');
208	  console.log('                                   pull values from GitHub Environments, then');
209	  console.log('                                   auto-fill Contentful tokens if possible');
210	  console.log('  npm run env -- validate        — check all existing env files for mistakes');
211	  console.log('  npm run env -- validate --live — also confirm Contentful + SFCC credentials actually work');
212	  console.log(`  npm run env -- push <${GH_SCOPES.join('|')}>`);
213	  console.log('                                   — tier-1-approvers only: push local values up to');
214	  console.log('                                   the matching GitHub Environment');
215	  console.log('  npm run env -- <tier>          — switch to <tier>');
216	}
217	
218	async function initAll() {
219	  const sharedPath = path.join(ROOT, '.env.shared');
220	  const created = [];
221	  const skipped = [];
222	  let totalBlanks = 0;
223	
224	  if (fs.existsSync(sharedPath)) {
225	    skipped.push('.env.shared');
226	  } else {
227	    totalBlanks += scaffold(sharedPath, SHARED_FILE_ENTRIES, 'shared (all tiers)', true);
228	    created.push('.env.shared');
229	  }
230	
231	  for (const tier of TIERS) {
232	    const tierPath = path.join(ROOT, `.env.${tier}`);
233	    if (fs.existsSync(tierPath)) {
234	      skipped.push(`.env.${tier}`);
235	    } else {
236	      totalBlanks += scaffold(tierPath, TIER_ENTRIES, tier, false);
237	      created.push(`.env.${tier}`);
238	    }
239	  }
240	
241	  console.log('');
242	  if (created.length) {
243	    console.log(`Created ${created.length} file(s): ${created.join(', ')}`);
244	    console.log(`Fill in the ${totalBlanks} blank value(s) across them in one pass, then run:`);
245	    console.log('  npm run env -- validate     (check everything is filled in correctly)');
246	    console.log('  npm run env -- <tier>       (activate one)');
247	  } else {
248	    console.log('Nothing to do — every .env.shared / .env.<tier> file already exists.');
249	  }
250	  if (skipped.length) {
251	    console.log(`Already existed, left untouched: ${skipped.join(', ')}`);
252	  }
253	
254	  migrateSharedFromDotEnv();
255	  pullFromGitHubEnvironments();
256	  await syncContentfulTokens();
257	}
258	
259	// ── GitHub Environments (centralized shared/tier storage) ──────────────────
260	// One GitHub Environment per scope — "shared" plus one per tier — each holding
261	// that scope's values as Environment-level Variables. Reading a Variable only
262	// needs repo collaborator access (gh auto-detects the repo from cwd, no need
263	// to pass -R). Writing needs repo Admin, which every tier-1-approver already
264	// holds — see `push` in main(). This intentionally stores real secrets here
265	// (not just non-sensitive config) — a deliberate, confirmed override of
266	// AGENTS.md's "secrets only in .env / Managed Runtime" rule, accepting that
267	// GitHub Variables are plaintext and readable by any repo collaborator.
268	const GH_SCOPES = ['shared', ...TIERS];
269	
270	function listGitHubVariables(scope) {
271	  try {
272	    const raw = execSync(`gh variable list --env ${scope} --json name,value`, {
273	      encoding: 'utf8',
274	      stdio: ['ignore', 'pipe', 'pipe'],
275	    });
276	    return JSON.parse(raw);
277	  } catch {
278	    return null; // not authenticated, no access, or environment missing
279	  }
280	}
281	
282	function pullFromGitHubEnvironments() {
283	  console.log('\nPulling values from GitHub Environments...');
284	  for (const scope of GH_SCOPES) {
285	    const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
286	    if (!fs.existsSync(filePath)) continue;
287	    const remoteVars = listGitHubVariables(scope);
288	    if (!remoteVars) {
289	      console.log(`  ${scope}: could not reach GitHub (not authenticated, no access, or environment missing)`);
290	      continue;
291	    }
292	    // Personal-scope keys (e.g. JIRA_API_TOKEN, CONTENTFUL_MANAGEMENT_TOKEN) are
293	    // never pulled, even if one somehow ended up on GitHub — each developer's
294	    // own value must never be overwritten by whoever last pushed.
295	    const filtered = scope === 'shared' ? remoteVars.filter(({ name }) => !PERSONAL_KEYS.has(name)) : remoteVars;
296	    const skippedPersonal = remoteVars.length - filtered.length;
297	    const updates = Object.fromEntries(filtered.map(({ name, value }) => [name, value]));
298	    const changes = upsertKeys(filePath, updates, true);
299	    const summary = changes.length
300	      ? changes.map((change) => `${change.action} ${change.key}`).join(', ')
301	      : 'already up to date';
302	    console.log(
303	      `  ${scope}: ${summary}${
304	        skippedPersonal ? ` (ignored ${skippedPersonal} personal-scope value(s) found on GitHub — see NOTE below)` : ''
305	      }`,
306	    );
307	  }
308	}
309	
310	function pushToGitHubEnvironment(scope) {
311	  const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
312	  if (!fs.existsSync(filePath)) {
313	    console.error(`${path.relative(ROOT, filePath)} doesn't exist yet — run \`npm run env -- init\` first.`);
314	    process.exit(1);
315	  }
316	
317	  const { approved, login } = isTier1Approver();
318	  if (!approved) {
319	    console.log(
320	      `Authenticated as '${login}' — not a tier-1-approver. Only tier-1-approvers can push to GitHub Environments.`,
321	    );
322	    return;
323	  }
324	
325	  const allEntries = readEnvFile(filePath).filter(([, value]) => value);
326	  // Personal-scope keys never leave this machine — pushing your own Jira/CMA
327	  // token would put every teammate's actions under your identity.
328	  const entries = scope === 'shared' ? allEntries.filter(([key]) => !PERSONAL_KEYS.has(key)) : allEntries;
329	  const skippedPersonal = allEntries.length - entries.length;
330	  if (skippedPersonal) {
331	    console.log(
332	      `Excluding ${skippedPersonal} personal-scope value(s) — these are never pushed: ${allEntries
333	        .filter(([key]) => PERSONAL_KEYS.has(key))
334	        .map(([key]) => key)
335	        .join(', ')}`,
336	    );
337	  }
338	  if (!entries.length) {
339	    console.log(`Nothing to push — ${path.relative(ROOT, filePath)} has no filled-in, push-eligible values yet.`);
340	    return;
341	  }
342	
343	  const tempFile = path.join(os.tmpdir(), `.env.push-${scope}.tmp`);
344	  fs.writeFileSync(tempFile, entries.map(([key, value]) => `${key}=${value}`).join('\n') + '\n');
345	  try {
346	    execSync(`gh variable set -f "${tempFile}" --env ${scope}`, { stdio: 'inherit' });
347	    console.log(`Pushed ${entries.length} value(s) to the "${scope}" GitHub Environment.`);
348	  } finally {
349	    fs.unlinkSync(tempFile);
350	  }
351	}
352	
353	// ── Contentful auto-fetch (init) ────────────────────────────────────────────
354	// Same tier-1-approver gate as scripts/contentful/setup/getConfig.mjs — kept as
355	// a small local copy rather than importing it, since it isn't exported there.
356	function isTier1Approver() {
357	  try {
358	    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
359	    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
360	      encoding: 'utf8',
361	    }).trim();
362	    const members = membersRaw.split('\n').filter(Boolean);
363	    return { approved: members.includes(login), login };
364	  } catch {
365	    return { approved: false, login: 'unknown' };
366	  }
367	}
368	
369	// contentful-management errors stringify their `.message` as the full raw API
370	// error body (headers, request id, everything) — pull out just the human part.
371	function contentfulErrorMessage(err) {
372	  try {
373	    const parsed = JSON.parse(err.message);
374	    if (parsed?.message) return parsed.message;
375	  } catch {
376	    // not JSON — fall through to the raw message
377	  }
378	  return err.message;
379	}
380	
381	async function fetchContentfulTokenMap(managementToken, spaceId) {
382	  process.env.CONTENTFUL_MANAGEMENT_TOKEN = managementToken;
383	  process.env.CONTENTFUL_SPACE_ID = spaceId;
384	  const client = createContentfulClient();
385	
386	  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
387	  const tokenMap = {};
388	  for (const key of apiKeys) {
389	    const envLink = key.environments?.[0];
390	    if (!envLink) continue;
391	    const envId = envLink.sys.id;
392	    let previewToken = '';
393	    if (key.preview_api_key?.sys?.id) {
394	      try {
395	        const previewKey = await client.previewApiKey.get({ previewApiKeyId: key.preview_api_key.sys.id });
396	        previewToken = previewKey.accessToken;
397	      } catch {
398	        // non-fatal — preview key may not exist yet
399	      }
400	    }
401	    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
402	  }
403	  return tokenMap;
404	}
405	
406	function parseEnvLines(content) {
407	  return content.split('\n').map((line) => {
408	    if (line.startsWith('#') || line.trim() === '') return { type: 'raw', value: line };
409	    const eqIdx = line.indexOf('=');
410	    if (eqIdx === -1) return { type: 'raw', value: line };
411	    return { type: 'var', key: line.slice(0, eqIdx).trim(), value: line.slice(eqIdx + 1) };
412	  });
413	}
414	
415	function serializeEnvLines(lines) {
416	  return lines.map((line) => (line.type === 'var' ? `${line.key}=${line.value}` : line.value)).join('\n');
417	}
418	
419	// Updates only the given keys in place, preserving comments/ordering/everything
420	// else — unlike scaffold(), which is only used for brand-new files. With
421	// fillOnly, an already-non-blank existing value is left alone instead of being
422	// overwritten — used for one-off migration from a pre-existing .env, where we
423	// never want to silently clobber something the dev already set by hand.
424	function upsertKeys(filePath, updates, canWrite, fillOnly = false) {
425	  const lines = parseEnvLines(fs.readFileSync(filePath, 'utf8'));
426	  const changes = [];
427	  for (const [key, value] of Object.entries(updates)) {
428	    if (!value) continue;
429	    const existing = lines.find((line) => line.type === 'var' && line.key === key);
430	    if (!existing) {
431	      lines.push({ type: 'var', key, value });
432	      changes.push({ action: 'add', key });
433	    } else if (!existing.value.trim()) {
434	      existing.value = value;
435	      changes.push({ action: 'fill', key });
436	    } else if (!fillOnly && existing.value.trim() !== value) {
437	      existing.value = value;
438	      changes.push({ action: 'update', key });
439	    }
440	  }
441	  if (changes.length && canWrite) {
442	    fs.writeFileSync(filePath, serializeEnvLines(lines));
443	  }
444	  return changes;
445	}
446	
447	// One-off backfill: if a pre-existing root .env already has real values for
448	// shared-scope keys (e.g. a Contentful management token a dev added before
449	// this tiered setup existed), pull them into .env.shared. Only shared-scope
450	// keys — tier-scope values in an old .env can't be safely attributed to any
451	// one tier, so those are never auto-migrated. No tier-1 gate: this only copies
452	// a secret between two local gitignored files the developer already owns.
453	function migrateSharedFromDotEnv() {
