24	/**
25	 * @typedef {Object} FieldDefinition
26	 * @property {string} id
27	 * @property {string} name
28	 * @property {string} type
29	 * @property {string} [linkType]
30	 * @property {boolean} [required]
31	 * @property {Record<string, unknown>} [defaultValue]
32	 * @property {string} [helpText]
33	 * @property {Array<Record<string, unknown>>} [validations]
